import static bootcamp.Check.*;

import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

class Exercise {

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Transactional {}

    /** Records what a PlatformTransactionManager was asked to do. */
    static class TxManager {
        final List<String> log = new ArrayList<>();
        boolean active;
        void begin() { active = true; log.add("begin"); }
        void commit() { active = false; log.add("commit"); }
        void rollback() { active = false; log.add("rollback"); }
    }

    interface OrderService {
        @Transactional void placeOrder(String id);
        @Transactional void refund(String id) throws Exception;
        @Transactional void checkout(String id);
        void importAll(List<String> ids);
        void importAllViaSelf(List<String> ids);
        int placed();
    }

    /** A proxy implementing iface that runs @Transactional methods of target inside a transaction. */
    static <T> T transactional(T target, Class<T> iface, TxManager tx) {
        InvocationHandler handler = (proxy, method, args) -> {
            boolean owner = method.isAnnotationPresent(Transactional.class) && !tx.active;   // REQUIRED: join an active one
            if (owner) tx.begin();
            Object result;
            try {
                result = method.invoke(target, args);
            } catch (InvocationTargetException e) {
                Throwable cause = e.getCause();
                if (owner) {
                    if (cause instanceof RuntimeException || cause instanceof Error) tx.rollback();
                    else tx.commit();             // checked exceptions commit unless rollbackFor says otherwise
                }
                throw cause;
            }
            if (owner) tx.commit();
            return result;
        };
        return iface.cast(Proxy.newProxyInstance(iface.getClassLoader(), new Class<?>[] { iface }, handler));
    }

