        int queries;
        boolean open = true;

        Session(Map<Long, String> customers) { this.customers = customers; }

        /** one SELECT; a closed session cannot query */
        String selectCustomerName(long id) {
            if (!open) throw new IllegalStateException("Session is closed");
            queries++;
            return customers.get(id);
        }

